@Component("agreement-handler")
@ProcessingGroup("agreement-processing-group")
public class AgreementEventHandler {
	
	// core constructor
	AgreementEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAgreementEvent
     */
    @EventHandler
    public void handle( CreateAgreementEvent event) {
        entityManager.persist(new Agreement(event.getAgreementId(), event.getAgreementNumber(), event.getEffectiveDate(), event.getCustomer(), event.getProductOffering(), event.getAgreementType(), event.getStatus()));
    }

    /*
     * @param	event UpdateAgreementEvent
     */
    @EventHandler
    public Agreement handle( UpdateAgreementEvent event) {
    	entityManager.merge(new Agreement(event.getAgreementId(), event.getAgreementNumber(), event.getEffectiveDate(), event.getCustomer(), event.getProductOffering(), event.getAgreementType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAgreementEvent
     */
    @EventHandler
    public void on( DeleteAgreementEvent event) {
    	Agreement entity = new Agreement();
   
    	// ------------------------------------------
    	// apply the AgreementId
    	// ------------------------------------------
    	entity.setAgreementId( event.getAgreementId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AgreementRepository agreementEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AgreementEventHandler.class.getName());

}
